<?php
namespace App\Policies;use App\Domain\Tenancy\TenantContext;use App\Models\{PrivilegedAccessGrant,User};final class PrivilegedAccessGrantPolicy{public function viewAny(User$u):bool{return$u->memberships()->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','COMPLIANCE_ADMIN'])->exists();}public function view(User$u,PrivilegedAccessGrant$x):bool{return$x->tenant_id===app(TenantContext::class)->id()&&$this->viewAny($u);}public function update(User$u,PrivilegedAccessGrant$x):bool{return$this->view($u,$x);}}
